use std::fs

const BAD: int = -99999999

fn is_leap(y: int) -> bool {
    (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

fn days_in_month(y: int, m: int) -> int {
    if m == 2 {
        if is_leap(y) { 29 } else { 28 }
    } else if m == 4 || m == 6 || m == 9 || m == 11 {
        30
    } else {
        31
    }
}

fn days_from_civil(y0: int, m: int, d: int) -> int {
    let y = if m <= 2 { y0 - 1 } else { y0 }
    let era = y / 400
    let yoe = y - era * 400
    let mp = (m + 9) % 12
    let doy = (153 * mp + 2) / 5 + d - 1
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy
    era * 146097 + doe - 719468
}

fn num(cs: Vec<char>, a: int, b: int) -> int {
    let mut v = 0
    let mut i = a
    while i < b {
        let c = cs[i as usize]
        if c < '0' || c > '9' {
            return -1
        }
        v = v * 10 + (c as int - '0' as int)
        i += 1
    }
    v
}

fn parse_date(s: string) -> int {
    let cs: Vec<char> = s.chars().collect()
    if cs.len() != 10 {
        return BAD
    }
    if cs[4] != '-' || cs[7] != '-' {
        return BAD
    }
    let y = num(cs, 0, 4)
    let m = num(cs, 5, 7)
    let d = num(cs, 8, 10)
    if y < 0 || m < 1 || m > 12 || d < 1 {
        return BAD
    }
    if d > days_in_month(y, m) {
        return BAD
    }
    days_from_civil(y, m, d)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let names = ["Thursday", "Friday", "Saturday", "Sunday", "Monday", "Tuesday", "Wednesday"]
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if parts.len() != 2 {
            println("invalid")
            continue
        }
        let a = parse_date(parts[0])
        let b = parse_date(parts[1])
        if a == BAD || b == BAD {
            println("invalid")
            continue
        }
        let lo = if a < b { a } else { b }
        let diff = if a < b { b - a } else { a - b }
        let wd = ((lo % 7) + 7) % 7
        println("${diff} ${names[wd as usize]}")
    }
}

